function convertTemp(value, from, to){
  from=String(from).toLowerCase(); to=String(to).toLowerCase();
  value=Number(value);
  if(isNaN(value)) throw new Error('数值无效');
  var c;
  if(from==='c') c=value;
  else if(from==='f') c=(value-32)*5/9;
  else if(from==='k') c=value-273.15;
  else if(from==='r') c=(value-491.67)*5/9;
  else throw new Error('未知单位 '+from);
  var res;
  if(to==='c') res=c;
  else if(to==='f') res=c*9/5+32;
  else if(to==='k') res=c+273.15;
  else if(to==='r') res=c*9/5+491.67;
  else throw new Error('未知单位 '+to);
  return res;
}
function fmt(n){
  if(!isFinite(n)) return String(n);
  var r=Math.round(n*1e4)/1e4;
  return String(r);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { convertTemp:convertTemp, fmt:fmt };
}
if (typeof window !== 'undefined') {
  window.TempForgePure = { convertTemp:convertTemp, fmt:fmt };
}
